def scal_odmowy_bez_firmy(apps, schema_editor):
    """
    Jeden wiersz bez firmy na powód i dzień, zanim ograniczenie tego zażąda.

    Duplikaty mogły powstać przy równoległych pierwszych odmowach dnia (P17).
    Suma liczby, najwcześniejsza pierwsza, najpóźniejsza ostatnia odmowa;
    zgłoszone, jeśli zgłoszony był którykolwiek - żeby scalenie nie
    wywołało drugiego alarmu o tym samym dniu.
    """
    ZliczenieOdmow = apps.get_model("accounts", "ZliczenieOdmow")
    grupy = (
        ZliczenieOdmow.objects.filter(tenant__isnull=True)
        .values("powod", "dzien")
        .annotate(
            ile=models.Count("id"),
            liczba_razem=Sum("liczba"),
            pierwsza_min=Min("pierwsza"),
            ostatnia_max=Max("ostatnia"),
        )
        .filter(ile__gt=1)
    )
    for grupa in grupy:
        wiersze = ZliczenieOdmow.objects.filter(
            tenant__isnull=True, powod=grupa["powod"], dzien=grupa["dzien"]
        ).order_by("id")
        zostaje = wiersze.first()
        zgloszone = wiersze.filter(zgloszone=True).exists()
        wiersze.exclude(pk=zostaje.pk).delete()
        ZliczenieOdmow.objects.filter(pk=zostaje.pk).update(
            liczba=grupa["liczba_razem"],
            pierwsza=grupa["pierwsza_min"],
            ostatnia=grupa["ostatnia_max"],
            zgloszone=zgloszone,
        )


